export function t(key, ...args) {
  const v = D[lang.value][key] ?? D.ro[key] ?? key
  return typeof v === 'function' ? v(...args) : v
}

export const catName = (c) => (c ? (lang.value === 'ru' ? c.name_ru : c.name_ro) : '')
